package decision

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/ollama/ollama/api"
)

func TestPublisherPrompts(t *testing.T) {
	var req Request
	if err := json.Unmarshal([]byte(`{"model":"decision","state":"Paid €20 & <tag>. Literal \\u2028, quote \" and colon: comma,","questions":{"refund":{"type":"noul","instructions":"Refund requested?"}}}`), &req); err != nil {
		t.Fatal(err)
	}
	// Publisher contracts: Together's examples/decide.py payload(), with
	// false/true described as No/Yes, and Bespoke's native_schema(), which
	// describes only the choices the request describes.
	for _, tc := range []struct{ renderer, want string }{
		{"tev1", `{"state": "Paid €20 & <tag>. Literal \\u2028, quote \" and colon: comma,", "question": "Refund requested?", "options": [{"label": "A", "key": "false", "description": "No"}, {"label": "B", "key": "true", "description": "Yes"}]}`},
		{"", `{"context": "Paid €20 & \u003ctag\u003e. Literal \\u2028, quote \" and colon: comma,", "schema": [{"name": "refund", "description": "Refund requested?", "choices": [{"code": "A", "value": false}, {"code": "B", "value": true}]}]}` + "\n\nRequested field: \"refund\""},
	} {
		t.Run(tc.renderer, func(t *testing.T) {
			compiled, err := Compile(req, tc.renderer)
			if err != nil {
				t.Fatal(err)
			}
			if err := compiled.Render(func(messages []api.Message) (string, error) { return messages[0].Content, nil }); err != nil {
				t.Fatal(err)
			}
			if got := compiled.Request.Rows[0].Prompt; got != tc.want {
				t.Fatalf("prompt differs from publisher format:\ngot  %s\nwant %s", got, tc.want)
			}
		})
	}
}

func TestTevQuestions(t *testing.T) {
	req := testRequest(t)
	req.State = json.RawMessage(`{"frames":["first","second"]}`)
	compiled, err := Compile(req, "tev1")
	if err != nil {
		t.Fatal(err)
	}
	if err := compiled.Render(func(messages []api.Message) (string, error) { return messages[0].Content, nil }); err != nil {
		t.Fatal(err)
	}
	descriptions := [][]string{{"Charges and refunds", "technical"}, {"No", "Yes"}, {"Routine", "Urgent", "Emergency"}}
	for i, row := range compiled.Request.Rows {
		var payload struct {
			State    json.RawMessage
			Question string
			Options  []struct{ Label, Key, Description string }
		}
		if err := json.Unmarshal([]byte(row.Prompt), &payload); err != nil {
			t.Fatal(err)
		}
		f := compiled.fields[i]
		if string(payload.State) != `{"frames": ["first", "second"]}` || payload.Question != f.Description || len(payload.Options) != len(f.Choices) {
			t.Fatalf("question %d was not compiled independently: %s", i, row.Prompt)
		}
		for j, option := range payload.Options {
			if option.Label != row.Candidates[j] || option.Description != descriptions[i][j] || option.Key == "" {
				t.Fatalf("question %d option %d: %+v", i, j, option)
			}
		}
	}
	for _, count := range []int{24, 25, 26} {
		q, _ := req.Questions.Get("department")
		criteria := make([]string, count)
		for i := range criteria {
			criteria[i] = fmt.Sprintf(`"%d":"x"`, i)
		}
		q.Criteria = json.RawMessage(`{` + strings.Join(criteria, ",") + `}`)
		req.Questions.Set("department", q)
		_, err := Compile(req, "tev1")
		if (err == nil) != (count == 24) {
			t.Errorf("Tev1 accepted %d candidates: %v", count, err)
		}
	}
}

package server

import (
	"context"
	"strings"
	"testing"
	"time"
)

func TestGetAuthorizationTokenRejectsCrossDomain(t *testing.T) {
	tests := []struct {
		realm        string
		originalHost string
		wantMismatch bool
	}{
		{"https://example.com/token", "example.com", false},
		{"https://example.com/token", "other.com", true},
		{"https://example.com/token", "localhost:8000", true},
		{"https://localhost:5000/token", "localhost:5000", false},
		{"https://localhost:5000/token", "localhost:6000", true},
	}

	for _, tt := range tests {
		t.Run(tt.originalHost, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
			defer cancel()

			challenge := registryChallenge{Realm: tt.realm, Service: "test", Scope: "repo:x:pull"}
			_, err := getAuthorizationToken(ctx, challenge, tt.originalHost)

			isMismatch := err != nil && strings.Contains(err.Error(), "does not match")
			if tt.wantMismatch && !isMismatch {
				t.Errorf("expected domain mismatch error, got: %v", err)
			}
			if !tt.wantMismatch && isMismatch {
				t.Errorf("unexpected domain mismatch error: %v", err)
			}
		})
	}
}

func TestParseRegistryChallenge(t *testing.T) {
	tests := []struct {
		input                             string
		wantRealm, wantService, wantScope string
	}{
		{
			`Bearer realm="https://auth.example.com/token",service="registry",scope="repo:foo:pull"`,
			"https://auth.example.com/token", "registry", "repo:foo:pull",
		},
		{
			`Bearer realm="https://r.ollama.ai/v2/token",service="ollama",scope="-"`,
			"https://r.ollama.ai/v2/token", "ollama", "-",
		},
		{"", "", "", ""},
	}

	for _, tt := range tests {
		result := parseRegistryChallenge(tt.input)
		if result.Realm != tt.wantRealm || result.Service != tt.wantService || result.Scope != tt.wantScope {
			t.Errorf("parseRegistryChallenge(%q) = {%q, %q, %q}, want {%q, %q, %q}",
				tt.input, result.Realm, result.Service, result.Scope,
				tt.wantRealm, tt.wantService, tt.wantScope)
		}
	}
}

func TestRegistryChallengeURL(t *testing.T) {
	challenge := registryChallenge{
		Realm:   "https://auth.example.com/token",
		Service: "registry",
		Scope:   "repo:foo:pull repo:bar:push",
	}

	u, err := challenge.URL()
	if err != nil {
		t.Fatalf("URL() error: %v", err)
	}

	if u.Host != "auth.example.com" {
		t.Errorf("host = %q, want %q", u.Host, "auth.example.com")
	}
	if u.Path != "/token" {
		t.Errorf("path = %q, want %q", u.Path, "/token")
	}

	q := u.Query()
	if q.Get("service") != "registry" {
		t.Errorf("service = %q, want %q", q.Get("service"), "registry")
	}
	if scopes := q["scope"]; len(scopes) != 2 {
		t.Errorf("scope count = %d, want 2", len(scopes))
	}
	if q.Get("ts") == "" {
		t.Error("missing ts")
	}
	if q.Get("nonce") == "" {
		t.Error("missing nonce")
	}

	// Nonces should differ between calls
	u2, _ := challenge.URL()
	if q.Get("nonce") == u2.Query().Get("nonce") {
		t.Error("nonce should be unique per call")
	}
}

func TestRegistryChallengeURLInvalid(t *testing.T) {
	challenge := registryChallenge{Realm: "://invalid"}
	if _, err := challenge.URL(); err == nil {
		t.Error("expected error for invalid URL")
	}
}

